package sdk

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/ahp-platform/ahp/pkg/contracts"
	sdkstate "github.com/ahp-platform/ahp/sdk/go/state"
)

// Task represents an A2A task context after SDK processing.
type Task struct {
	// ThreadID is the State API thread (derived from contextId).
	ThreadID string
	// RunID is the State API run (derived from taskId).
	RunID string
	// ContextID is the A2A contextId.
	ContextID string
	// TaskID is the authenticated AHP task, which may differ from the opaque
	// A2A taskId generated by the protocol server.
	TaskID string
	// Payload is the task input (A2A message parts or workflow params).
	Payload json.RawMessage
}

// RunContext bundles everything a graph execution needs: lease, checkpoint
// saver, KV store, intent recorder, and task metadata.
type RunContext struct {
	// Lease is the active lease with auto-heartbeat.
	Lease *ActiveLease
	// Task is the A2A task metadata.
	Task Task
	// CheckpointSaver is scoped to this lease and thread.
	CheckpointSaver *CheckpointSaver
	// Store is the KV state for this run.
	Store *AHPStore
	// Intents records operation keys for side effects.
	Intents *IntentRecorder
	// Config is the SDK configuration.
	Config *Config
}

// GraphFunc is the user-supplied graph execution function. It receives a
// RunContext with all State API access, and returns the graph output.
// If the graph needs to wait for input (interrupt), return an InterruptError.
type GraphFunc func(ctx context.Context, rc *RunContext) (json.RawMessage, error)

// InterruptError signals that the graph reached an interrupt() and needs
// external input to resume. The SDK translates this to Suspend + input-required.
type InterruptError struct {
	WaitFor string
	Payload json.RawMessage
}

func (e *InterruptError) Error() string { return "sdk: graph interrupted, waiting for input" }

// RunResult is the outcome of a complete run execution.
type RunResult struct {
	// Status is "done", "failed", or "waiting".
	Status string
	// Output is the graph output (nil for waiting).
	Output json.RawMessage
}

// App manages the A2A task lifecycle: claim → execute → release.
type App struct {
	cfg   *Config
	graph GraphFunc
}

// NewApp creates an App with the given configuration and graph function.
func NewApp(cfg *Config, graph GraphFunc) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	if graph == nil {
		return nil, fmt.Errorf("sdk: graph function must not be nil")
	}
	return &App{cfg: cfg, graph: graph}, nil
}

// RunOnceFor executes exactly ONE named task's run: it verifies the binding
// BEFORE taking a lease, then claims that run by id and runs the graph.
//
// The verification is the point. A run carries the payload, the budget lineage and
// the audit trail of the task that created it, so executing "the run I happened to
// claim" with "the task I was asked about" is not a harmless optimisation: it books
// one task's work under another task's fence. RunOnceFor therefore refuses -- with
// the lease untouched -- when the named run belongs to a different task, sits in a
// different context, or carries a different payload than the caller believes.
//
// It returns (nil, nil) when the run is not claimable right now (another run owns
// the thread's head, or the run is already terminal): nothing was executed and
// nothing was written.
func (a *App) RunOnceFor(ctx context.Context, task Task) (*RunResult, error) {
	if task.RunID == "" || task.TaskID == "" {
		return nil, contracts.NewError(contracts.ErrInvalid, "sdk: RunOnceFor needs the run and the task it belongs to; an unbound claim is refused")
	}
	stored, err := a.cfg.StateClient.GetRun(ctx, task.RunID)
	if err != nil {
		return nil, fmt.Errorf("sdk: cannot verify run %s before claiming it: %w", task.RunID, err)
	}
	if stored.TaskID != task.TaskID {
		return nil, contracts.NewError(contracts.ErrInvalid, fmt.Sprintf("sdk: run %s belongs to task %s, not %s -- refusing to execute a payload under another task's run and fence", task.RunID, stored.TaskID, task.TaskID))
	}
	if task.ContextID != "" && stored.ThreadID == "" {
		return nil, contracts.NewError(contracts.ErrInvalid, "sdk: run has no thread to bind the task context to")
	}
	if !samePayload(stored.Payload, task.Payload) {
		return nil, contracts.NewError(contracts.ErrInvalid, fmt.Sprintf("sdk: run %s carries a different payload than task %s states -- refusing to run a new payload under an existing run", task.RunID, task.TaskID))
	}

	lease, err := claimAndHold(ctx, a.cfg, task.RunID)
	if err != nil {
		return nil, err
	}
	if lease == nil {
		return nil, nil
	}
	if lease.RunID() != task.RunID {
		// Cannot happen against an honest State, and this path never bets on that:
		// the claim is dropped without executing anything.
		lease.cancel()
		return nil, contracts.NewError(contracts.ErrInvalid, fmt.Sprintf("sdk: claim returned run %s while %s was named", lease.RunID(), task.RunID))
	}

	runCtx, err := a.buildRunContext(ctx, lease)
	if err != nil {
		// The failed close states its reason (DEF-RELEASE-REASON-1) and its refusal is
		// never swallowed: a run left non-terminal because the close was refused is a
		// hazard the caller has to see, not a detail of a best-effort cleanup.
		if closeErr := lease.ReleaseWithReason(ctx, sdkstate.RunFailed, "error"); closeErr != nil {
			err = fmt.Errorf("%w; durable close: %v", err, closeErr)
		}
		return &RunResult{Status: sdkstate.RunFailed}, err
	}

	output, err := a.graph(lease.Context(), runCtx)
	if lease.IsLost() {
		err = lease.LostReason()
	}
	if err == nil && ctx.Err() != nil {
		err = ctx.Err()
	}
	if err != nil {
		var ie *InterruptError
		if isInterrupt(err, &ie) {
			if suspendErr := lease.Suspend(ctx, ie.WaitFor, nil); suspendErr != nil {
				return &RunResult{Status: sdkstate.RunFailed}, suspendErr
			}
			return &RunResult{Status: sdkstate.RunWaiting}, nil
		}
		if closeErr := lease.ReleaseWithReason(ctx, sdkstate.RunFailed, "error"); closeErr != nil {
			err = fmt.Errorf("%w; durable close: %v", err, closeErr)
		}
		return &RunResult{Status: sdkstate.RunFailed}, err
	}

	if err := lease.Release(ctx, sdkstate.RunDone); err != nil {
		return &RunResult{Status: sdkstate.RunFailed}, err
	}
	return &RunResult{Status: sdkstate.RunDone, Output: output}, nil
}

// RunTasks drives the polling loop over tasks the caller NAMES, until each has
// reached an outcome or ctx is canceled. There is no "process whatever the queue
// hands me" loop any more: the loop must know which task it is serving.
func (a *App) RunTasks(ctx context.Context, tasks []Task, pollInterval time.Duration) error {
	if len(tasks) == 0 {
		return contracts.NewError(contracts.ErrInvalid, "sdk: RunTasks needs at least one task to serve")
	}
	if pollInterval <= 0 {
		pollInterval = time.Second
	}
	pending := append([]Task(nil), tasks...)
	for len(pending) > 0 {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}
		remaining := make([]Task, 0, len(pending))
		for _, t := range pending {
			result, err := a.RunOnceFor(ctx, t)
			if err != nil {
				return err
			}
			if result == nil {
				remaining = append(remaining, t)
			}
		}
		if len(remaining) == 0 {
			return nil
		}
		pending = remaining
		timer := time.NewTimer(pollInterval)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
	}
	return nil
}

// samePayload compares what the caller believes the task carries with what the
// durable run actually carries. Absent payloads (empty, null or "{}") are the same
// absence on both sides; anything else must match byte for byte after trimming,
// because a payload is an effect-bearing input, not a display field.
func samePayload(stored, claimed json.RawMessage) bool {
	empty := func(b []byte) bool {
		t := strings.TrimSpace(string(b))
		return t == "" || t == "null" || t == "{}"
	}
	if empty(stored) || empty(claimed) {
		return empty(stored) && empty(claimed)
	}
	return strings.TrimSpace(string(stored)) == strings.TrimSpace(string(claimed))
}

// EnsureThreadAndRun creates the thread and run for a new A2A task and returns
// what State ACTUALLY recorded.
//
// contextId -> thread (idempotent by contextId), taskId -> run (idempotent by key).
// The returned TaskID is the durable run's task identity, which State mints from
// the verified credential rather than from the caller's string, so a caller cannot
// carry a belief about the task identity that the ledger does not share. Where the
// two disagree the caller is told, because the disagreement is exactly the moment a
// later claim would be refused: an A2A taskId is only usable as a task identity if
// the presenting credential says the same thing.
func (a *App) EnsureThreadAndRun(ctx context.Context, contextID, taskID string, payload json.RawMessage) (Task, error) {
	thread, err := a.cfg.StateClient.CreateThread(ctx, contextID, "ctx:"+contextID)
	if err != nil {
		return Task{}, fmt.Errorf("sdk: CreateThread: %w", err)
	}
	run, err := a.cfg.StateClient.CreateRun(ctx, thread.ID, "task:"+taskID, payload)
	if err != nil {
		return Task{}, fmt.Errorf("sdk: CreateRun: %w", err)
	}
	if run.TaskID != taskID {
		return Task{}, contracts.NewError(contracts.ErrInvalid, fmt.Sprintf("sdk: run %s was recorded under task %q, not the A2A taskId %q -- the presenting credential, not the caller, names a task; present the task's own credential", run.ID, run.TaskID, taskID))
	}
	return Task{
		ThreadID:  thread.ID,
		RunID:     run.ID,
		ContextID: contextID,
		TaskID:    run.TaskID,
		Payload:   run.Payload,
	}, nil
}

func (a *App) buildRunContext(ctx context.Context, lease *ActiveLease) (*RunContext, error) {
	threadID := lease.ThreadID()
	return &RunContext{
		Lease:           lease,
		CheckpointSaver: NewCheckpointSaver(lease.cfg.StateClient, lease.Fence(), threadID),
		Store:           NewAHPStore(lease.cfg.StateClient, lease.Fence()),
		Intents:         NewIntentRecorder(lease.cfg.StateClient, lease.Fence(), lease.RunID()),
		Config:          lease.cfg,
		Task:            Task{ThreadID: threadID, RunID: lease.RunID(), TaskID: lease.claim.Lease.Run.TaskID, ContextID: lease.claim.Lease.Thread.ContextID, Payload: lease.claim.Lease.Run.Payload},
	}, nil
}

func isInterrupt(err error, target **InterruptError) bool {
	for err != nil {
		if ie, ok := err.(*InterruptError); ok {
			*target = ie
			return true
		}
		type unwrapper interface{ Unwrap() error }
		if u, ok := err.(unwrapper); ok {
			err = u.Unwrap()
		} else {
			return false
		}
	}
	return false
}
